if doc.product:
    product_doc = frappe.get_doc("Products", doc.product)

    # Set product-level fields only if not already set
    if not doc.roi and product_doc.default_roi:
        doc.roi = product_doc.default_roi
    if not doc.tenure and product_doc.tenure_default:
        doc.tenure = product_doc.tenure_default

    if not doc.tenureunit and product_doc.tenure:
        doc.tenureunit = product_doc.tenure    

    if not doc.roi_type and product_doc.roi_type:
        doc.roi_type = product_doc.roi_type

    if not doc.roi_unit and product_doc.roi_unit:
        doc.roi_unit = product_doc.roi_unit

    if not doc.day_of_month_of_emi and product_doc.day_of_emi:
        doc.day_of_month_of_emi = product_doc.day_of_emi

    if not doc.pre_interest and product_doc.pre_interest:
        doc.pre_interest = product_doc.pre_interest

    # Copy child table rows if loan_roi is empty
    if not doc.loan_roi:
        for row in product_doc.partner:
            doc.append("loan_roi", {
                "partner": row.partner,
                "partnertype": row.partnertype,
                "principle": row.principle,
                "roi": row.roi,
                "tenure": row.tenure
            })

if doc.create_emi_trnx == "Ready to create":
    for row in doc.emi_calculator:
        if not row.status_emi or row.status_emi == "Pending":
            row.status_emi = "Ready to create"

    doc.db_set("create_emi_trnx", "Created")
    frappe.msgprint("EMI entries marked 'Ready to create' and transaction set to 'Created'.")

# Check if logic is empty
if not doc.logic and doc.product:
    # Fetch settlement_logic from the linked Product
    product = frappe.get_doc("Products", doc.product)
    if product.settlement_logic:
        doc.logic = product.settlement_logic

# Normalize all component names to lowercase
for row in doc.components:
    if row.component:
        row.component = row.component.lower()

    # Step 0: Clear old values before applying logic
    row.amount_settled = 0
    row.amount_due = 0

# Get logic order from doc.logic, fallback to "ipc" if not provided
logic_order = (doc.logic or "ipc").lower().strip()

# Initialize remaining amount from paid
remaining_amount = doc.emi_amount_paid or 0

# Case 1: Full payment — mark all as settled
if doc.emi_amount_paid == doc.emi_amount:
    for row in doc.components:
        row.amount_settled = row.amount or 0

# Case 2: Partial payment — settle based on priority in logic_order
else:
    for priority in logic_order:
        for row in doc.components:
            if row.component.startswith(priority):
                row.amount = row.amount or 0
                row.amount_settled = row.amount_settled or 0

                unsettled = row.amount - row.amount_settled
                to_settle = min(unsettled, remaining_amount)
                row.amount_settled = row.amount_settled + to_settle
                remaining_amount = remaining_amount - to_settle

                if remaining_amount <= 0:
                    break
        if remaining_amount <= 0:
            break

# Final step: Calculate amount_due for all components
for row in doc.components:
    row.amount = row.amount or 0
    row.amount_settled = row.amount_settled or 0
    row.amount_due = row.amount - row.amount_settled

if doc.logic and doc.debit and doc.collection:

    used_debit_names = set()

    sorted_collections = sorted(
        doc.collection,
        key=lambda c: frappe.utils.getdate(c.collection_date)
    )

    sorted_debits = sorted(
        doc.debit,
        key=lambda d: frappe.utils.get_datetime(d.disbursement_date)
    )

    current_invoice_index = 0  # Index of active invoice

    for collection in sorted_collections:

        if (collection.settled_amount or 0) >= (collection.collection_amount or 0):
            continue

        if (collection.settled_amount or 0) == 0 and (collection.excess_amount or 0) == 0:
            collection.excess_amount = collection.collection_amount

        remaining_collection = float(collection.excess_amount or 0)

        while remaining_collection > 0 and current_invoice_index < len(sorted_debits):

            debit = sorted_debits[current_invoice_index]

            principle = float(debit.outstanding_principle_amount or 0)
            roi = float(debit.roi or 0)
            disbursement_date = frappe.utils.get_datetime(debit.disbursement_date)
            invoice_id = debit.invoice_id

            if debit.last_payment_date:
                last_payment = frappe.utils.get_datetime(debit.last_payment_date)
            else:
                last_payment = disbursement_date

            collection_date = frappe.utils.get_datetime(collection.collection_date)

            if frappe.utils.getdate(last_payment) == frappe.utils.getdate(disbursement_date) and doc.interest_accrual_starting == "same day":
                start_date = frappe.utils.add_days(last_payment, -1)
            else:
                start_date = last_payment

            start_day = frappe.utils.getdate(start_date)
            collection_day = frappe.utils.getdate(collection_date)

            tenure_updated = 0
            if collection_day > start_day:
                tenure_updated = (collection_day - start_day).days

            previous_interest_accrued = 0.0
            i = len(doc.transaction) - 1
            while i >= 0:
                t = doc.transaction[i]
                if t.invoice_number == invoice_id:
                    previous_interest_accrued = float(t.interest_due or 0)
                    i = -1
                else:
                    i = i - 1

            fresh_interest = 0.0
            if tenure_updated > 0 and roi > 0 and principle > 0:
                fresh_interest = (roi / 100.0) * principle * tenure_updated / 365.0

            total_interest_due = previous_interest_accrued + fresh_interest

            principle_settled = 0.0
            interest_settled = 0.0
            charges = 0.0
            charges_settled = 0.0
            new_outstanding = principle

            if doc.logic == "PIC":
                if principle > 0:
                    if remaining_collection >= principle:
                        principle_settled = principle
                        new_outstanding = 0.0
                        remaining_collection = remaining_collection - principle
                    else:
                        principle_settled = remaining_collection
                        new_outstanding = principle - remaining_collection
                        remaining_collection = 0.0

                if new_outstanding == 0.0 and remaining_collection > 0 and total_interest_due > 0.0:
                    to_settle = total_interest_due
                    if remaining_collection < total_interest_due:
                        to_settle = remaining_collection
                    interest_settled = to_settle
                    remaining_collection = remaining_collection - to_settle

            elif doc.logic == "IPC":
                if principle == 0.0:
                    to_settle = total_interest_due
                    if remaining_collection < total_interest_due:
                        to_settle = remaining_collection
                    interest_settled = to_settle
                    remaining_collection = remaining_collection - to_settle

                if remaining_collection > 0 and principle > 0:
                    if remaining_collection >= principle:
                        principle_settled = principle
                        new_outstanding = 0.0
                        remaining_collection = remaining_collection - principle
                    else:
                        principle_settled = remaining_collection
                        new_outstanding = principle - remaining_collection
                        remaining_collection = 0.0

            if principle_settled > 0 or interest_settled > 0:
                principle_due = principle - principle_settled
                interest_due = total_interest_due - interest_settled
                charges_due = charges - charges_settled
                used_amount = principle_settled + interest_settled + charges_settled
                amount_balance = float(collection.collection_amount or 0) - used_amount
                if amount_balance < 0:
                    amount_balance = 0.0

                txn = doc.append("transaction", {})
                txn.collection_date = collection.collection_date
                txn.collection_amount = float(collection.collection_amount or 0)
                txn.invoice_number = invoice_id
                txn.principle = principle
                txn.tenure_updated = tenure_updated
                txn.interest = total_interest_due
                txn.previous_interest_accrued = previous_interest_accrued
                txn.charges = charges
                txn.principle_settled = principle_settled
                txn.interest_settled = interest_settled
                txn.charges_settled = charges_settled
                txn.interest_due = interest_due
                txn.principle_due = principle_due
                txn.charges_due = charges_due
                txn.amount_balance = amount_balance

                debit.outstanding_principle_amount = new_outstanding

                if principle_settled > 0:
                    debit.last_payment_date = collection.collection_date

                used_debit_names.add(debit.name)

            # Move to next invoice only if current is fully settled
            if doc.logic == "PIC":
                if new_outstanding == 0.0 and total_interest_due <= interest_settled:
                    current_invoice_index = current_invoice_index + 1
            elif doc.logic == "IPC":
                if new_outstanding == 0.0:
                    current_invoice_index = current_invoice_index + 1

        # Update collection status
        total_settled = 0.0
        for txn in doc.transaction:
            if txn.collection_date == collection.collection_date:
                total_settled = total_settled + float(txn.principle_settled or 0)
                total_settled = total_settled + float(txn.interest_settled or 0)

        collection.settled_amount = total_settled
        collection.excess_amount = float(collection.collection_amount or 0) - total_settled

    # Recalculate outstanding principals
    for debit in doc.debit:
        if debit.name not in used_debit_names:
            has_txn = False
            total_settled = 0.0
            for txn in doc.transaction:
                if txn.invoice_number == debit.invoice_id:
                    has_txn = True
                    total_settled = total_settled + float(txn.principle_settled or 0)
            if has_txn:
                debit.outstanding_principle_amount = float(debit.disbursement_amount or 0) - total_settled
            else:
                debit.outstanding_principle_amount = float(debit.disbursement_amount or 0)

if doc.product:
    product_doc = frappe.get_doc("Products", doc.product)

    # If interest_accrual_starting is "Default", copy from the Product
    if doc.interest_accrual_starting == "Default" and product_doc.interest_accrual_starting:
        doc.interest_accrual_starting = product_doc.interest_accrual_starting

    # If doc.roi is empty, and product has a default ROI, copy it
    if not doc.roi and product_doc.default_roi:
        doc.roi = product_doc.default_roi

