            invoice_id = debit.invoice_id

            if debit.last_payment_date:
                last_payment = frappe.utils.get_datetime(debit.last_payment_date)
            else:
                last_payment = disbursement_date

            collection_date = frappe.utils.get_datetime(collection.collection_date)

            if frappe.utils.getdate(last_payment) == frappe.utils.getdate(disbursement_date) and doc.interest_accrual_starting == "same day":
                start_date = frappe.utils.add_days(last_payment, -1)
            else:
