            interest_end_day = collection_day
            if collection_day > due_day:
                interest_end_day = due_day

            if interest_end_day > start_day:
                tenure_days = (interest_end_day - start_day).days
            else:
                tenure_days = 0

            tenure_updated = tenure_days

            previous_interest_accrued = 0.0
            previous_charges_due = 0.0
            for t in doc.transaction[::-1]:
                if t.invoice_number == invoice_id:
                    previous_interest_accrued = float(t.interest_due or 0)
                    previous_charges_due = float(t.charges_due or 0)
                    break

            fresh_interest = 0.0
            if tenure_days > 0 and roi > 0 and principle > 0:
                fresh_interest = (roi / 100.0) * principle * tenure_days / 365.0

            charges = 0.0
            charges_days = 0
