                if debit.last_payment_date and frappe.utils.get_datetime(debit.last_payment_date) > due_date:
                    overdue_start_date = frappe.utils.get_datetime(debit.last_payment_date)
                else:
                    overdue_start_date = due_date

                if frappe.utils.getdate(collection_date) > frappe.utils.getdate(overdue_start_date):
                    overdue_days = (frappe.utils.getdate(collection_date) - frappe.utils.getdate(overdue_start_date)).days
