                        new_outstanding = 0.0
                        remaining_collection = remaining_collection - principle
                    else:
                        principle_settled = remaining_collection
                        new_outstanding = principle - remaining_collection
                        remaining_collection = 0.0

                if new_outstanding == 0.0 and total_interest_due > 0.0 and remaining_collection > 0:
                    if remaining_collection >= total_interest_due:
                        interest_settled = total_interest_due
                        remaining_collection = remaining_collection - total_interest_due
                    else:
                        interest_settled = remaining_collection
                        remaining_collection = 0.0

                if int(doc.collect_charges_before or 0) == 1:
                    if new_outstanding == 0.0 and (total_interest_due - interest_settled) <= 0.0 and total_charges_due > 0.0 and remaining_collection > 0:
                        if remaining_collection >= total_charges_due:
                            charges_settled = total_charges_due
                            remaining_collection = remaining_collection - total_charges_due
                        else:
                            charges_settled = remaining_collection
                            remaining_collection = 0.0
                    else:
                        charges_settled = 0.0

            elif doc.logic == "IPC":

                if total_interest_due > 0.0 and remaining_collection > 0:
                    if remaining_collection >= total_interest_due:
                        interest_settled = total_interest_due
                        remaining_collection = remaining_collection - total_interest_due
                    else:
                        interest_settled = remaining_collection
                        remaining_collection = 0.0

                if (total_interest_due - interest_settled) <= 0.0 and principle > 0 and remaining_collection > 0:
                    if remaining_collection >= principle:
                        principle_settled = principle
                        new_outstanding = 0.0
                        remaining_collection = remaining_collection - principle
                    else:
                        principle_settled = remaining_collection
                        new_outstanding = principle - remaining_collection
                        remaining_collection = 0.0

                if int(doc.collect_charges_before or 0) == 1:
                    if new_outstanding == 0.0 and (total_interest_due - interest_settled) <= 0.0 and total_charges_due > 0.0 and remaining_collection > 0:
                        if remaining_collection >= total_charges_due:
                            charges_settled = total_charges_due
                            remaining_collection = remaining_collection - total_charges_due
                        else:
                            charges_settled = remaining_collection
                            remaining_collection = 0.0
                    else:
                        charges_settled = 0.0

            if principle_settled > 0 or interest_settled > 0 or charges_settled > 0:

                principle_due = principle - principle_settled
                interest_due = total_interest_due - interest_settled
                charges_due = total_charges_due - charges_settled
                used_amount = principle_settled + interest_settled + charges_settled
                amount_balance = float(collection.collection_amount or 0) - used_amount
                if amount_balance < 0:
                    amount_balance = 0.0

                previous_balance = None
                for t in doc.transaction[::-1]:
                    if t.collection_date == collection.collection_date:
                        previous_balance = float(t.amount_balance or 0)
                        break

                if previous_balance is not None:
                    collection_amount_used = previous_balance
                else:
                    collection_amount_used = float(collection.collection_amount or 0)

                txn = doc.append("transaction", {})
                txn.collection_date = collection.collection_date
                txn.collection_amount = collection_amount_used
                txn.invoice_number = invoice_id
                txn.principle = principle
                txn.tenure_updated = tenure_updated
                txn.interest = fresh_interest
                txn.previous_interest_accrued = previous_interest_accrued
                txn.previous_charges_due = previous_charges_due
                txn.charges = charges
                txn.charges_days = charges_days
                txn.principle_settled = principle_settled
                txn.interest_settled = interest_settled
                txn.charges_settled = charges_settled
                txn.interest_due = interest_due
                txn.principle_due = principle_due
                txn.charges_due = charges_due
                txn.amount_balance = amount_balance
                txn.collection_amount_used = used_amount

                debit.outstanding_principle_amount = new_outstanding
                if principle_settled > 0:
                    debit.last_payment_date = collection.collection_date

                used_debit_names.add(debit.name)

            charges_due_remaining = total_charges_due - charges_settled
            charges_block = int(doc.collect_charges_before or 0) == 1 and charges_due_remaining > 0.0

            move_next = False
            if new_outstanding == 0.0 and (total_interest_due - interest_settled) <= 0.0 and not charges_block:
                move_next = True

            if move_next:
                current_invoice_index = current_invoice_index + 1

        total_settled = 0.0
        for txn in doc.transaction:
