            roi = float(debit.roi or 0)
            disbursement_date = frappe.utils.get_datetime(debit.disbursement_date)
            due_date = frappe.utils.get_datetime(debit.due_date)
            invoice_id = debit.invoice_id

            if debit.last_payment_date:
                last_payment = frappe.utils.get_datetime(debit.last_payment_date)
                if last_payment < disbursement_date:
                    last_payment = disbursement_date
            else:
                last_payment = disbursement_date

            collection_date = frappe.utils.get_datetime(collection.collection_date)

            if frappe.utils.getdate(last_payment) == frappe.utils.getdate(disbursement_date) and doc.interest_accrual_starting == "same day":
                start_date = frappe.utils.add_days(last_payment, -1)
            else:
                start_date = last_payment

            start_day = frappe.utils.getdate(start_date)
            collection_day = frappe.utils.getdate(collection_date)
            due_day = frappe.utils.getdate(due_date)

            interest_end_day = collection_day
            if collection_day > due_day:
                interest_end_day = due_day

            if interest_end_day > start_day:
                tenure_days = (interest_end_day - start_day).days
            else:
                tenure_days = 0

            tenure_updated = tenure_days

            previous_interest_accrued = 0.0
            previous_charges_due = 0.0
            for t in doc.transaction[::-1]:
                if t.invoice_number == invoice_id:
                    previous_interest_accrued = float(t.interest_due or 0)
                    previous_charges_due = float(t.charges_due or 0)
                    break

            fresh_interest = 0.0
            if tenure_days > 0 and roi > 0 and principle > 0:
                fresh_interest = (roi / 100.0) * principle * tenure_days / 365.0

            charges = 0.0
            charges_days = 0
            if collection_day > due_day and principle > 0:
                if debit.last_payment_date and frappe.utils.get_datetime(debit.last_payment_date) > due_date:
                    overdue_start_date = frappe.utils.get_datetime(debit.last_payment_date)
                else:
                    overdue_start_date = due_date

                if frappe.utils.getdate(collection_date) > frappe.utils.getdate(overdue_start_date):
                    overdue_days = (frappe.utils.getdate(collection_date) - frappe.utils.getdate(overdue_start_date)).days
                    charges_days = overdue_days
                    charges_base = principle + previous_interest_accrued + fresh_interest
                    charges = (charges_base * float(doc.overdue_charges or 0)) / 100.0 * overdue_days / 365.0

            total_interest_due = previous_interest_accrued + fresh_interest
            total_charges_due = previous_charges_due + charges

            principle_settled = 0.0
            interest_settled = 0.0
            charges_settled = 0.0
            new_outstanding = principle

            if doc.logic == "PIC":

                if principle > 0:
                    if remaining_collection >= principle:
                        principle_settled = principle
                        new_outstanding = 0.0
                        remaining_collection = remaining_collection - principle
                    else:
                        principle_settled = remaining_collection
                        new_outstanding = principle - remaining_collection
                        remaining_collection = 0.0

                if new_outstanding == 0.0 and total_interest_due > 0.0 and remaining_collection > 0:
                    if remaining_collection >= total_interest_due:
                        interest_settled = total_interest_due
                        remaining_collection = remaining_collection - total_interest_due
                    else:
                        interest_settled = remaining_collection
                        remaining_collection = 0.0

                if int(doc.collect_charges_before or 0) == 1:
                    if new_outstanding == 0.0 and (total_interest_due - interest_settled) <= 0.0 and total_charges_due > 0.0 and remaining_collection > 0:
                        if remaining_collection >= total_charges_due:
                            charges_settled = total_charges_due
                            remaining_collection = remaining_collection - total_charges_due
                        else:
                            charges_settled = remaining_collection
                            remaining_collection = 0.0

            elif doc.logic == "IPC":

                if total_interest_due > 0.0 and remaining_collection > 0:
                    if remaining_collection >= total_interest_due:
                        interest_settled = total_interest_due
                        remaining_collection = remaining_collection - total_interest_due
                    else:
                        interest_settled = remaining_collection
                        remaining_collection = 0.0

                if (total_interest_due - interest_settled) <= 0.0 and principle > 0 and remaining_collection > 0:
                    if remaining_collection >= principle:
                        principle_settled = principle
                        new_outstanding = 0.0
                        remaining_collection = remaining_collection - principle
                    else:
                        principle_settled = remaining_collection
                        new_outstanding = principle - remaining_collection
                        remaining_collection = 0.0

                if int(doc.collect_charges_before or 0) == 1:
                    if new_outstanding == 0.0 and (total_interest_due - interest_settled) <= 0.0 and total_charges_due > 0.0 and remaining_collection > 0:
                        if remaining_collection >= total_charges_due:
                            charges_settled = total_charges_due
                            remaining_collection = remaining_collection - total_charges_due
                        else:
                            charges_settled = remaining_collection
                            remaining_collection = 0.0

            if principle_settled > 0 or interest_settled > 0 or charges_settled > 0:

                principle_due = principle - principle_settled
                interest_due = total_interest_due - interest_settled
                charges_due = total_charges_due - charges_settled
                used_amount = principle_settled + interest_settled + charges_settled
                amount_balance = float(collection.collection_amount or 0) - used_amount
                if amount_balance < 0:
                    amount_balance = 0.0

                previous_balance = None
                for t in doc.transaction[::-1]:
                    if t.collection_date == collection.collection_date:
                        previous_balance = float(t.amount_balance or 0)
                        break

                if previous_balance is not None:
                    collection_amount_used = previous_balance
                else:
                    collection_amount_used = float(collection.collection_amount or 0)

                txn = doc.append("transaction", {})
                txn.collection_date = collection.collection_date
                txn.collection_amount = collection_amount_used
                txn.invoice_number = invoice_id
                txn.principle = principle
                txn.tenure_updated = tenure_updated
                txn.interest = fresh_interest
                txn.previous_interest_accrued = previous_interest_accrued
                txn.previous_charges_due = previous_charges_due
                txn.charges = charges
                txn.charges_days = charges_days
                txn.principle_settled = principle_settled
                txn.interest_settled = interest_settled
                txn.charges_settled = charges_settled
                txn.interest_due = interest_due
                txn.principle_due = principle_due
                txn.charges_due = charges_due
                txn.amount_balance = amount_balance
                txn.collection_amount_used = used_amount

                debit.outstanding_principle_amount = new_outstanding
                if principle_settled > 0:
                    debit.last_payment_date = collection.collection_date

                used_debit_names.add(debit.name)

            charges_due_remaining = total_charges_due - charges_settled
            charges_block = int(doc.collect_charges_before or 0) == 1 and charges_due_remaining > 0.0

            move_next = False
            if new_outstanding == 0.0 and (total_interest_due - interest_settled) <= 0.0 and not charges_block:
                move_next = True

            if move_next:
                current_invoice_index = current_invoice_index + 1

        total_settled = 0.0
        for txn in doc.transaction:
            if txn.collection_date == collection.collection_date:
                total_settled = total_settled + float(txn.principle_settled or 0)
                total_settled = total_settled + float(txn.interest_settled or 0)
                total_settled = total_settled + float(txn.charges_settled or 0)

        collection.settled_amount = total_settled
        collection.excess_amount = float(collection.collection_amount or 0) - total_settled

    total_disbursed = 0.0
    total_principle = 0.0
    total_collection = 0.0

    for d in doc.debit:
        total_disbursed = total_disbursed + float(d.disbursement_amount or 0)

    for t in doc.transaction:
        total_principle = total_principle + float(t.principle_settled or 0)

    for c in doc.collection:
        total_collection = total_collection + float(c.collection_amount or 0)

    doc.total_disbursed_amount = total_disbursed
    doc.total_principle_settled = total_principle
    doc.collection_amount = total_collection
